create or replace view t1 as select ws_item_sk, ws_order_number, min(ws_quantity) as ws_quantity, min(ws_item_sk) as ws_item_sk from web_sales, date_dim, web_page where ws_web_page_sk = wp_web_page_sk and ws_sold_date_sk = d_date_sk and d_year = 2001 and ws_sales_price between 50.00 and 200.00 group by ws_item_sk, ws_order_number;
select min(t1.ws_quantity), min(wr_refunded_cash), min(wr_fee), min(t1.ws_item_sk), min(t1.ws_order_number), min(cd1.cd_demo_sk), min(cd2.cd_demo_sk) from t1, web_returns, customer_demographics cd1, customer_demographics cd2, customer_address, reason where t1.ws_item_sk = wr_item_sk and t1.ws_order_number = wr_order_number and cd1.cd_demo_sk = wr_refunded_cdemo_sk and cd2.cd_demo_sk = wr_returning_cdemo_sk and ca_address_sk = wr_refunded_addr_sk and r_reason_sk = wr_reason_sk and ((cd1.cd_marital_status = 'M' and cd1.cd_marital_status = cd2.cd_marital_status and cd1.cd_education_status = 'College' and cd1.cd_education_status = cd2.cd_education_status) or (cd1.cd_marital_status = 'S' and cd1.cd_marital_status = cd2.cd_marital_status and cd1.cd_education_status = 'High School' and cd1.cd_education_status = cd2.cd_education_status) or (cd1.cd_marital_status = 'W' and cd1.cd_marital_status = cd2.cd_marital_status and cd1.cd_education_status = 'Graduate Degree' and cd1.cd_education_status = cd2.cd_education_status)) and ((ca_country = 'United States' and ca_state in ('CA', 'TX', 'NY')) or (ca_country = 'United States' and ca_state in ('FL', 'IL', 'PA')) or (ca_country = 'United States' and ca_state in ('OH', 'MI', 'GA')));